public class JArrayIncrementElements {
	public static void main(String[] args) {
		//Step 1: Define and initialize the array
	   int[] lst = { 1, 2, 3, 4, 5, 6 };
	   //Step 2: Iterate through the array elements 
	   for (int i = 0; i < lst.length; i++) {
		    //Step 2.1: Increment the element at index i by 1
	      lst[i] += 1;
	   }
		//Step 3: Print the array elements
	   for (int x : lst) {
		   System.out.print(x + "  ");
	   }
	}
}
